```go
package main

import "fmt"

// hasKey checks if the given key exists in the map.
func hasKey(m map[string]int, key string) bool {
    _, exists := m[key]
    return exists
}

func main() {
    myMap := map[string]int{"apple": 1, "banana": 2, "cherry": 3}

    // Check if the key "banana" exists in the map
