#import "Person.h"

// Define a comparator block that compares two Person objects based on their birthdate
NSComparator (^personBirthdateComparator)(Person *, Person *) = ^(Person *person1, Person *person2) {
    // Compare the birthdates using NSOrderedAscending or NSOrderedDescending
    return [person1.birthdate compare:person2.birthdate options:NSCompareDates];
};

// Create an array of Person objects (for demonstration)
